// --- Main Component ---
const SearchBarGen: React.FC<SearchBarGenProps> = ({
  backgroundColor = "#f0f4ff", 
  transparentBackground = false,
  durationInSeconds = 10,
  primaryButtonColor = "#1a1a1a",
  buttonTextColor = "#ffffff",
  glassOpacity = 0.25,
  showCursor = true,
  cursorDelay = 10,
  promptText = "Build me a travel itineray iOS app",
  fontSize = 22,
}) => {
  // Load Fonts
  useFontLoader(["Manrope", "Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // --- Intro Timing Configuration ---
  const typingDelay = 15;
  const typingDuration = 45; // Types the text
  const gapAfterTyping = 10;
  const transitionDuration = 35;
  
  // The frame where the "original" animation logic effectively starts
  const existingAnimationStart = typingDelay + typingDuration + gapAfterTyping + transitionDuration;

  // Offset frame for existing logic
  const effectiveFrame = frame - existingAnimationStart;

  // 1. Calculations & Constants (Original Logic using effectiveFrame)
  // Animation timing constants
  const enterStart = 0;
  const cursorStart = enterStart + cursorDelay;
  const cursorDuration = 40;
  const clickStart = cursorStart + cursorDuration + 10;

  // 2. Cursor Animation
  const cursorProgress = spring({
    frame: effectiveFrame - cursorStart,
    fps,
    config: { damping: 20, stiffness: 60 },
  });

  // Calculate cursor positions
  // We want the cursor to start off-screen right and land on the centered button
  const startX = width * 0.4; 
  const startY = height * 0.4;
  // Button is perfectly centered now, so target is near (0,0) center relative + slight offset for visual
  const targetX = 40; 
  const targetY = 20; 

  const cursorX = interpolate(cursorProgress, [0, 1], [startX, targetX]);
  const cursorY = interpolate(cursorProgress, [0, 1], [startY, targetY]);

  // 3. Button Interaction (Hover & Click)
  const hoverScale = interpolate(
    effectiveFrame,
    [cursorStart + cursorDuration - 10, cursorStart + cursorDuration],
    [1, 1.05],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const buttonClickScale = interpolate(
    effectiveFrame,
    [clickStart, clickStart + 5, clickStart + 12],
    [1, 0.95, 1],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp", easing: Easing.bezier(0.25, 1, 0.5, 1) }
  );

  const sparkleRotation = interpolate(
    effectiveFrame,
    [clickStart + 5, clickStart + 45],
    [0, 180],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.back(1.5)) }
  );
  
  const totalButtonScale = hoverScale * buttonClickScale;

  // 4. Intro & Layout Logic
  // Typing Animation
  const textToType = promptText;
  const typeProgress = interpolate(
    frame,
    [typingDelay, typingDelay + typingDuration],
    [0, 1],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }
  );
  const charsToShow = Math.round(typeProgress * textToType.length);
  const displayedText = textToType.substring(0, charsToShow);
  const showCaret = frame < existingAnimationStart && (frame % 30 < 15);

  // Intro Transition (Scale & Translate)
  const introScale = 1.6;
  const targetScale = 2.2;
  const introTranslateX = 140; // Shift visual center to prompt bar center
  const targetTranslateX = 0; // Center on button

  const transitionProgress = interpolate(
    frame,
    [existingAnimationStart - transitionDuration, existingAnimationStart],
    [0, 1],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.bezier(0.25, 1, 0.5, 1) }
  );

  const currentZoom = interpolate(transitionProgress, [0, 1], [introScale, targetScale]);
  const currentTranslateX = interpolate(transitionProgress, [0, 1], [introTranslateX, targetTranslateX]);

  const wrapperStyle: React.CSSProperties = {
    position: "relative",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    transform: `scale(${currentZoom}) translateX(${currentTranslateX}px)`,
    // Sizing is determined by the content (Button)
  };

  // The glass background bar is positioned relative to the button wrapper
  const glassBackgroundStyle: React.CSSProperties = {
    position: "absolute",
    right: -24, // Extends 24px past the right edge of the button (padding)
    top: "50%",
    transform: "translateY(-50%)",
    width: 2600, // Very wide to extend off-screen to the left
    height: 120,
    borderRadius: 60,
    backgroundColor: `rgba(255, 255, 255, ${glassOpacity})`,
    backdropFilter: "blur(20px)",
    boxShadow: "0 8px 32px 0 rgba(31, 38, 135, 0.15)",
    border: "1px solid rgba(255, 255, 255, 0.4)",
    zIndex: 0, // Behind button and icons
  };

  // New Text Layout Config
  const textWidth = 230;
  const iconGap = 20;
  const iconsWidth = 68; // 24 (Icon) + 20 (Gap) + 24 (Icon)

  // Icons are now positioned closer to the button (to the right of text)
  const iconsContainerStyle: React.CSSProperties = {
    position: "absolute",
    right: "100%", 
    marginRight: 20, // Closest to button
    top: "50%",
    transform: "translateY(-50%)",
    display: "flex",
    gap: 20,
    opacity: 0.6,
    zIndex: 1, 
  };

  // Text is now positioned further left (to the left of icons)
  const textContainerStyle: React.CSSProperties = {
    position: "absolute",
    right: "100%", // Anchored to left edge of button
    marginRight: 20 + iconsWidth + iconGap, // Shifted to accommodate icons
    top: "50%",
    transform: "translateY(-50%)",
    width: textWidth,
    height: 40,
    display: "flex",
    alignItems: "center",
    justifyContent: "flex-end", // Updated alignment: text grows from right-to-left
    fontFamily: "Manrope",
    fontSize: fontSize,
    fontWeight: 500,
    color: "#333",
    zIndex: 1,
    whiteSpace: "nowrap",
    textAlign: "right", // Ensure text stays anchored to the right side near icons
  };

  const buttonStyle: React.CSSProperties = {
    position: "relative",
    zIndex: 2,
    backgroundColor: primaryButtonColor,
    color: buttonTextColor,
    border: "none",
    borderRadius: 40,
    padding: "14px 32px",
    fontSize: 22,
    fontWeight: 600,
    cursor: "pointer",
    display: "flex",
    alignItems: "center",
    gap: 12,
    boxShadow: "0 4px 15px rgba(0,0,0,0.2)",
    transform: `scale(${totalButtonScale})`, // Only button scales
    transformOrigin: "center",
    whiteSpace: "nowrap",
  };

  const cursorStyle: React.CSSProperties = {
    position: "absolute",
    left: "50%",
    top: "50%",
    // Apply dynamic currentZoom to cursor as well to keep proportions
    transform: `translate(${cursorX}px, ${cursorY}px) scale(${currentZoom})`,
    zIndex: 100,
    opacity: showCursor && effectiveFrame >= 0 ? 1 : 0, // Only show mouse cursor after intro
    filter: "drop-shadow(0px 4px 4px rgba(0,0,0,0.2))",
  };

  return (
    <AbsoluteFill
      style={{
        background: transparentBackground 
          ? undefined 
          : `linear-gradient(115deg, #c3dafe 0%, #e2e8ff 40%, #e8cffc 100%)`,
        fontFamily: "Manrope",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      {/* --- Centered Wrapper (Button Driven Layout) --- */}
      <div style={wrapperStyle}>
        
        {/* 1. Glass Background (Absolute) */}
        <div style={glassBackgroundStyle} />

        {/* 2. Left Icons (Absolute - Positioned right of text, left of button) */}
        <div style={iconsContainerStyle}>
          <PlusIcon color="#666" />
          <PaperclipIcon color="#666" />
        </div>

        {/* 3. Typed Text (Absolute - Positioned left of icons) */}
        <div style={textContainerStyle}>
          {displayedText}
          <span style={{ 
            display: "inline-block", 
            width: 2, 
            height: fontSize + 2, 
            backgroundColor: "#333", 
            marginLeft: 2,
            opacity: showCaret ? 1 : 0 
          }} />
        </div>

        {/* 4. The Button (Relative Anchor) */}
        <div style={buttonStyle}>
          {/* Sparkles Group */}
          <div style={{ position: "relative", width: 24, height: 24 }}>
             {/* Main Star */}
             <div style={{
               position: "absolute",
               inset: 0,
               display: "flex",
               alignItems: "center",
               justifyContent: "center",
               transform: `rotate(${sparkleRotation}deg)`
             }}>
                <Star 
                  points={4} 
                  innerRadius={4} 
                  outerRadius={10} 
                  fill={buttonTextColor} 
                />
             </div>
             {/* Small Star */}
             <div style={{
               position: "absolute",
               inset: 0,
               display: "flex",
               alignItems: "center",
               justifyContent: "center",
               transform: `translate(12px, -9px) rotate(${sparkleRotation * -1.5}deg) scale(0.5)`
             }}>
                <Star 
                  points={4} 
                  innerRadius={4} 
                  outerRadius={10} 
                  fill={buttonTextColor} 
                />
             </div>
          </div>
          
          <span style={{ position: 'relative', top: 1 }}>Generate</span>
        </div>
      </div>

      {/* --- Cursor --- */}
      {showCursor && (
        <div style={cursorStyle}>
          <CursorIcon color="black" stroke="white" />
        </div>
      )}

    </AbsoluteFill>
  );
};

export default SearchBarGen;